import json, re
from docx import Document

with open('employee_data.json') as f:
    data=json.load(f)

doc=Document('offer_letter_template.docx')

# function to process paragraph text
pattern_if = re.compile(r"\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}")


def replace_text(text):
    # conditional block
    def repl_if(m):
        if str(data.get('RELOCATION_PACKAGE','')).strip().lower()=='yes':
            return m.group(1)
        else:
            return ''
    text = pattern_if.sub(repl_if, text)
    # replace placeholders
    for k,v in data.items():
        text = text.replace('{{'+k+'}}', str(v))
    return text

# replace in paragraphs
for p in doc.paragraphs:
    if '{{' in p.text:
        new_text = replace_text(p.text)
        p.text = new_text

# replace in tables
for t in doc.tables:
    for row in t.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                if '{{' in p.text:
                    p.text = replace_text(p.text)

# remove any leftover markers
for p in doc.paragraphs:
    if '{{IF_RELOCATION}}' in p.text or '{{END_IF_RELOCATION}}' in p.text:
        p.text = p.text.replace('{{IF_RELOCATION}}','').replace('{{END_IF_RELOCATION}}','')

out='/root/offer_letter_filled.docx'

doc.save(out)
print('saved', out)
PY
